package com.vgc.entity.event.photoexhibition;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="photo_exhibition_votes",indexes={@Index(name="idx_exhibition_vote_event",columnList="event_id"),@Index(name="idx_exhibition_vote_submission",columnList="submission_id"),@Index(name="idx_exhibition_vote_voter",columnList="voter_id")},uniqueConstraints=@UniqueConstraint(name="uk_exhibition_voter_work",columnNames={"event_id","voter_id","submission_id"}))
public class PhotoExhibitionVote {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="event_id",nullable=false) private com.vgc.entity.event.Event event; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="voter_id",nullable=false) private com.vgc.entity.User voter; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="submission_id",nullable=false) private PhotoExhibitionSubmission submission; @Column(name="created_at",nullable=false) private LocalDateTime createdAt; @PrePersist void p(){createdAt=LocalDateTime.now();} public PhotoExhibitionVote(){} public PhotoExhibitionVote(com.vgc.entity.event.Event e,com.vgc.entity.User v,PhotoExhibitionSubmission s){event=e;voter=v;submission=s;} public PhotoExhibitionSubmission getSubmission(){return submission;} public com.vgc.entity.User getVoter(){return voter;} public LocalDateTime getCreatedAt(){return createdAt;} }
